steps.run:
set -euo pipefail
rust_cli=target/debug/symvault
rust_probe=target/debug/examples/egress_contract_probe
python3 scripts/rust-port/egress_contract.py --rust-cli "$rust_cli" --rust-probe "$rust_probe" --receipt target/native-egress.json
python3 - <<'PY'
import json, subprocess
from pathlib import Path
receipt = json.loads(Path('target/native-egress.json').read_bytes())
assert receipt['passed'] and receipt['candidate_worktree_clean'] and receipt['candidate_worktree_clean_at_end']
assert not subprocess.check_output(['git','status','--porcelain=v1','--untracked-files=normal']).strip()
assert receipt['candidate_commit'] == subprocess.check_output(['git','rev-parse','HEAD'], text=True).strip()
assert receipt['native_os'] in {'Linux','Darwin'}
runtime = {'tls-auth-bearer','tls-auth-basic','tls-auth-header','tls-auth-query_param','tls-auth-none','tls-all-substitution-surfaces','method-denied','endpoint-denied','encoded-endpoint-allowed','encoded-endpoint-denied','dot-segment-policy','unmatched-forwarded','unmatched-strict','passthrough-preserves-upstream-tls','untrusted-upstream-tls','template-port-binding','template-plaintext-binding','connect-inner-authority-binding','redirect-authority-binding'}
cli = {'broker-missing-vault','broker-boolean-forms','run-broker-flags-reach-vault','run-broker-disabled','run-broker-public-env','run-broker-strict-passthrough','run-broker-child-error','run-broker-timeout','run-broker-explicit-env','run-broker-launch-error','standalone-broker','standalone-broker-flags','loopback-listener-policy','concurrent-broker-ca-isolation'}
for implementation in ['go','rust']:
    assert runtime == {row['case'] for row in receipt[implementation]}
    assert cli == {row['case'] for row in receipt[implementation+'_cli']}
PY
